    mutationFn: (pasted: string) =>
      postJson<PasteResult>(
        `/api/sheets/${encodeURIComponent(sheet)}/paste-claims?user=${encodeURIComponent(user)}`,
        { text: pasted },
      ),
    onSuccess: async (result) => {
      setText('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
